frame_eqs_eel:
kick = max(bass - bass_att, 0);
pulse = max(pulse * 0.86, min(kick * 0.9, 1));
q3 = pulse;
phase = phase + 0.002 + 0.004 * min(bass_att, 2) + 0.01 * q3;
orbit = orbit + 0.0015 + 0.002 * min(mid_att, 2);
q1 = phase;
q2 = orbit;

warp:
uniform sampler2D sampler_fw_cover;
 shader_body {

  vec2 s = texsize.xy / min(texsize.x, texsize.y);

  vec2 p = (uv_orig - 0.5) * s;
  float r = length(p);
  float seg = 6.2831853 / 6.0;
  float a = mod(atan(p.y, p.x) + q1, seg);
  a = abs(a - seg * 0.5);
  vec2 k = vec2(cos(a), sin(a)) * r * (0.75 - 0.08 * clamp(bass_att, 0.0, 2.0) - 0.08 * q3);
  k += vec2(0.5, 0.5) + 0.24 * vec2(cos(q2), sin(q2 * 0.7));
  float cl = dot(texture(sampler_fw_cover, vec2(k.x, 1.0 - k.y)).xyz, vec3(0.299, 0.587, 0.114));
  float lum = clamp((cl - 0.5) * 1.9 + 0.5, 0.0, 1.0);

  vec3 fb = texture(sampler_main, uv).xyz * 0.88;
  ret = max(fb, vec3((1.0 - lum) * 0.5 * clamp(bass_att - 0.7, 0.0, 1.5)));
 }

comp:
uniform sampler2D sampler_fw_cover;
 shader_body {

  vec2 s = texsize.xy / min(texsize.x, texsize.y);

  vec2 p = (uv - 0.5) * s;
  float r = length(p);
  float seg = 6.2831853 / 6.0;
  float a = mod(atan(p.y, p.x) + q1, seg);
  a = abs(a - seg * 0.5);
  vec2 k = vec2(cos(a), sin(a)) * r * (0.75 - 0.08 * clamp(bass_att, 0.0, 2.0) - 0.08 * q3);
  k += vec2(0.5, 0.5) + 0.24 * vec2(cos(q2), sin(q2 * 0.7));
  float cl = dot(texture(sampler_fw_cover, vec2(k.x, 1.0 - k.y)).xyz, vec3(0.299, 0.587, 0.114));
  float lum = clamp((cl - 0.5) * 1.9 + 0.5, 0.0, 1.0);

  float col_r_x = clamp(lum, 0.0, 1.0) * 5.0;
  vec3 col_r = mix(NOKKVI_RAMP0, NOKKVI_RAMP1, clamp(col_r_x, 0.0, 1.0));
  col_r = mix(col_r, NOKKVI_RAMP2, clamp(col_r_x - 1.0, 0.0, 1.0));
  col_r = mix(col_r, NOKKVI_RAMP3, clamp(col_r_x - 2.0, 0.0, 1.0));
  col_r = mix(col_r, NOKKVI_RAMP4, clamp(col_r_x - 3.0, 0.0, 1.0));
  col_r = mix(col_r, NOKKVI_RAMP5, clamp(col_r_x - 4.0, 0.0, 1.0));

  vec3 col = mix(NOKKVI_BG, col_r, smoothstep(0.02, 0.35, lum));
  col = mix(col, NOKKVI_TEXT, smoothstep(0.85, 1.0, lum) * 0.7);

  col += NOKKVI_HIGHLIGHT * GetBlur1(uv) * 0.7;
  col += NOKKVI_WARM * smoothstep(0.85, 1.0, lum) * clamp(treb_att - 0.9, 0.0, 1.0) * 0.35;
  col += NOKKVI_TEXT * smoothstep(0.012, 0.0, abs(r - 0.35 - 0.2 * q3)) * q3 * 0.5;
  col *= 0.7 + 0.3 * smoothstep(0.9, 0.15, r);
  ret = col;
 }
